INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4803656, 693631, 24454, '<td valign="top">FABULOUS!</td>', 'FABULOUS!', '2008-07-05 01:20:19.000000', NULL, 1),
(4803732, 694352, 71244, '<td valign="top">lovely. my only 10.</td>', 'lovely. my only 10.', '2008-07-05 01:56:59.000000', NULL, 1),
