(4813916, 692997, 89341, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=697253" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697253.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697253.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697253.gif"/></a> from me in <a href="//dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=797556" rel="nofollow" target="_blank">Posthumous Ribbons</a> <br/> <br/>Love the colours and patterns in this, the Artichoke is very striking. The trail of colours into the photo is great as well.</td>', ' from me in Posthumous Ribbons  Love the colours and patterns in this, the Artichoke is very striking. The trail of colours into the photo is great as well.', '2008-07-09 07:19:23.000000', NULL, 0),
(4813921, 692796, 89341, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=697251" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697251.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697251.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/85000-89999/89341/120/697251.gif"/></a> from me in <a href="//dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=797556" rel="nofollow" target="_blank">Posthumous Ribbons</a> <br/> <br/>I love the POV of this and the foreground corn reaching up into the sky</td>', ' from me in Posthumous Ribbons  I love the POV of this and the foreground corn reaching up into the sky', '2008-07-09 07:20:21.000000', NULL, 0),
